<script setup>
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {getOverviewStatistics,getPopularMatches,getSalesTrend,getClubStatistics,getRefundStatistics,getCheckinStatistics} from '../../api/statistics'
const router=useRouter(),loading=ref(false),overview=ref({}),popular=ref([]),trend=ref([]),clubs=ref([]),refunds=ref({}),checkins=ref({})
const money=v=>`￥${Number(v||0).toFixed(2)}`,rate=v=>`${Number(v||0).toFixed(2)}%`
const load=async()=>{loading.value=true;try{const [a,b,c,d,e,f]=await Promise.all([getOverviewStatistics(),getPopularMatches({limit:5}),getSalesTrend(),getClubStatistics(),getRefundStatistics(),getCheckinStatistics()]);overview.value=a.data;popular.value=b.data;trend.value=c.data;clubs.value=d.data.slice(0,5);refunds.value=e.data;checkins.value=f.data}finally{loading.value=false}}
onMounted(load)
</script>
<template><div v-loading="loading"><div class="title"><h2>运营统计总览</h2><el-button type="primary" @click="router.push('/admin/statistics/matches')">比赛统计</el-button></div><el-row :gutter="14"><el-col :span="5"><el-card shadow="never"><div class="label">净销售额</div><b>{{money(overview.netSalesAmount)}}</b></el-card></el-col><el-col :span="5"><el-card shadow="never"><div class="label">有效售票量</div><b>{{overview.validTicketsSold||0}}</b></el-card></el-col><el-col :span="5"><el-card shadow="never"><div class="label">退票金额</div><b>{{money(overview.refundAmount)}}</b></el-card></el-col><el-col :span="4"><el-card shadow="never"><div class="label">已检票</div><b>{{overview.checkedInTickets||0}}</b></el-card></el-col><el-col :span="5"><el-card shadow="never"><div class="label">平均上座率</div><b>{{rate(overview.averageAttendanceRate)}}</b></el-card></el-col></el-row><el-row :gutter="16" class="section"><el-col :span="12"><el-card><template #header><b>销售趋势</b></template><el-table :data="trend" max-height="310"><el-table-column prop="statDate" label="日期"/><el-table-column label="毛销售额"><template #default="{row}">{{money(row.grossSalesAmount)}}</template></el-table-column><el-table-column label="退票"><template #default="{row}">{{money(row.refundAmount)}}</template></el-table-column><el-table-column label="净销售额"><template #default="{row}">{{money(row.netSalesAmount)}}</template></el-table-column></el-table></el-card></el-col><el-col :span="12"><el-card><template #header><b>热门比赛</b></template><el-table :data="popular" max-height="310"><el-table-column label="比赛" min-width="190"><template #default="{row}">{{row.homeClubName}} vs {{row.awayClubName}}</template></el-table-column><el-table-column prop="validSoldCount" label="有效售票"/><el-table-column label="售票率"><template #default="{row}">{{rate(row.ticketSaleRate)}}</template></el-table-column><el-table-column label="净销售额"><template #default="{row}">{{money(row.netSalesAmount)}}</template></el-table-column></el-table></el-card></el-col></el-row><el-row :gutter="16" class="section"><el-col :span="12"><el-card><template #header><b>俱乐部主场排行</b></template><el-table :data="clubs"><el-table-column prop="clubName" label="俱乐部"/><el-table-column prop="validTicketsSold" label="售票"/><el-table-column label="净销售额"><template #default="{row}">{{money(row.netSalesAmount)}}</template></el-table-column><el-table-column label="上座率"><template #default="{row}">{{rate(row.averageAttendanceRate)}}</template></el-table-column></el-table></el-card></el-col><el-col :span="12"><el-card><template #header><b>检票与退票</b></template><el-descriptions :column="2" border><el-descriptions-item label="检票尝试">{{checkins.totalAttempts||0}}</el-descriptions-item><el-descriptions-item label="成功率">{{rate(checkins.successRate)}}</el-descriptions-item><el-descriptions-item label="检票成功">{{checkins.successCount||0}}</el-descriptions-item><el-descriptions-item label="检票失败">{{checkins.failedCount||0}}</el-descriptions-item><el-descriptions-item label="退票申请">{{refunds.totalApplications||0}}</el-descriptions-item><el-descriptions-item label="退票率">{{rate(refunds.refundRate)}}</el-descriptions-item></el-descriptions></el-card></el-col></el-row></div></template>
<style scoped>.title{display:flex;align-items:center;justify-content:space-between}.label{color:#6b7280;margin-bottom:10px}.el-card b{font-size:22px}.section{margin-top:16px}</style>
